'use strict';
/* Financial Source Control — governed UI only. Candidate identifiers are
   selectable for read-only audit; no activation calls, Shaygan calls, invoice
   calls or inventory writes exist here. Backend authorization is authoritative. */
(()=>{
  const PAGE='financial-source-control',ROLES=['admin','accounting','manager'];
  const safe=value=>String(value==null?'':value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
  const num=value=>new Intl.NumberFormat('fa-IR').format(Number(value||0));
  const role=()=>String((typeof state!=='undefined'?state.user:window.state?.user)?.role||'');
  const api=async(url,options={})=>{const response=await fetch(url,{credentials:'include',cache:'no-store',headers:{Accept:'application/json','Content-Type':'application/json'},...options});const body=await response.json().catch(()=>({ok:false,error:'پاسخ نامعتبر سرور'}));if(!response.ok||body.ok===false){const error=new Error(body.error||response.statusText);error.code=body.code||'';error.status=response.status;throw error;}return body;};
  const qs=(selector,root=document)=>root.querySelector(selector),qsa=(selector,root=document)=>[...root.querySelectorAll(selector)];
  const body=()=>qs('#fscBody');
  const errorBox=error=>`<div class="error"><b>${safe(error.code||'خطا')}</b> — ${safe(error.message||error)}</div>`;
  const statusLabel=value=>({PROVEN:'سود با مأخذ اثبات‌شده',PARTIAL:'مأخذ هزینه ناقص',UNKNOWN:'هزینه خرید نامشخص',stale:'نیازمند بازسازی با منابع جدید',NEEDS_REVIEW:'نیازمند بررسی',ACCOUNTING_REVIEW:'در بررسی حسابداری',DEFERRED:'موکول‌شده',draft:'پیش‌نویس',pending:'در انتظار تأیید',approved:'تأییدشده',rejected:'ردشده',BUILT:'ساخته‌شده',VALIDATED:'اعتبارسنجی‌شده',HUMAN_REVIEW:'بررسی انسانی',ACCOUNTING_APPROVED:'تأیید حسابداری',ADMIN_APPROVED:'تأیید مدیر',PURCHASE_MISSING_FROM_DATASET:'خرید رسمی خارج از Dataset فعلی',MANUAL_COST_REQUIRED:'نیازمند مدرک هزینه دستی',NEGATIVE_CHRONOLOGY:'فروش پیش از مأخذ خرید',OPENING_INVENTORY_CANDIDATE:'نامزد موجودی آغاز دوره'}[value]||value||'—');
  const selectorLabel=(name,id)=>`${String(name||'بدون نام').trim()} — ${String(id||'').trim()}`;
  const resolveSelector=(input,options,labelKey,idKey)=>{const value=String(input?.value||'').trim();if(!value)return '';const exact=(options||[]).find(row=>selectorLabel(row[labelKey],row[idKey])===value);return exact?.[idKey]||'';};
  const FIFO_FILTER_KEY='mkcrm.fsc.fifo.filters.v1',FIFO_DATASET_KEY='mkcrm.fsc.fifo.dataset.v1';
  const emptyFifoFilterState=()=>({invoice:'',item:'',sellerIdentity:'',categoryGuid:'',status:'',costSourceType:'',dateFrom:'',dateTo:'',saleValueMin:'',saleValueMax:'',profitMin:'',profitMax:'',marginMin:'',marginMax:''});
  const readStoredFifoFilters=()=>{try{return {...emptyFifoFilterState(),...JSON.parse(sessionStorage.getItem(FIFO_FILTER_KEY)||'{}')};}catch{return emptyFifoFilterState();}};
  const storeFifoFilters=value=>{const safeState=Object.fromEntries(Object.keys(emptyFifoFilterState()).map(key=>[key,String(value?.[key]||'').trim()]));sessionStorage.setItem(FIFO_FILTER_KEY,JSON.stringify(safeState));window.__fscFifoFilterState=safeState;return safeState;};
  const selectorValue=(options,id,labelKey,idKey)=>{const row=(options||[]).find(value=>String(value[idKey]||'')===String(id||''));return row?selectorLabel(row[labelKey],row[idKey]):'';};
  function requireStableSelector(input,options,labelKey,idKey,label){const text=String(input?.value||'').trim();if(!text)return '';const identity=resolveSelector(input,options,labelKey,idKey);if(identity)return identity;const error=new Error(`${label} باید از فهرست رسمی انتخاب شود.`);error.code='FSC_SELECTOR_IDENTITY_REQUIRED';throw error;}
  const card=(title,row)=>`<div class="card"><div class="card-header"><h5>${safe(title)}</h5></div><div class="card-body">${row?`<div class="row four"><div><small>شناسه</small><br><b>${safe(row.datasetId)}</b></div><div><small>وضعیت</small><br>${safe(statusLabel(row.activationStatus||row.status))}</div><div><small>تعداد فاکتور / ردیف</small><br>${num(row.invoiceCount)} / ${num(row.lineCount||row.allocations)}</div><div><small>Fingerprint مأخذ</small><br><code title="${safe(row.sourceFingerprint)}">${safe((row.sourceFingerprint||'—').slice(0,18))}</code></div></div><div class="muted mt">بازه ${safe(row.dateFrom||'—')} تا ${safe(row.dateTo||'—')} | الگوریتم: ${safe(row.algorithmVersion||'—')} | ساخته‌شده: ${safe(row.completedAt||row.createdAt||'—')}</div>`:'<div class="warn">Dataset در دسترس نیست.</div>'}</div></div>`;
  function reviewControls(kind,source){if(!source?.candidate)return '';const review=source.review||{},stateValue=review.state||'BUILT',revision=Number(review.revision||0),buttons=[];if(['admin','accounting'].includes(role())&&['BUILT','VALIDATED'].includes(stateValue))buttons.push(['start-review','شروع بررسی انسانی']);if(['admin','accounting'].includes(role())&&stateValue==='HUMAN_REVIEW')buttons.push(['accounting-approve','تأیید حسابداری و ارسال برای مدیر']);if(['admin','manager'].includes(role())&&stateValue==='ACCOUNTING_APPROVED'){buttons.push(['admin-approve','تأیید Gate مدیر (بدون فعال‌سازی)']);buttons.push(['reject','بازگشت/رد']);}return `<div class="info"><b>${kind==='purchase-dataset'?'Purchase Candidate':'FIFO Candidate'}</b> — وضعیت Review: ${safe(statusLabel(stateValue))} / revision ${num(revision)} ${buttons.map(([action,label])=>`<button class="mini fscReviewAction" data-kind="${kind}" data-id="${safe(source.candidate.datasetId)}" data-action="${action}" data-revision="${revision}">${safe(label)}</button>`).join('')}<br><small>ADMIN_APPROVED در این Phase به معنی activation نیست؛ فعال‌سازی جداگانه و غیرفعال است.</small></div>`;}
  async function loadOverview(){const [overview,queues]=await Promise.all([api('/api/accounting/financial-source-control/overview'),api('/api/accounting/financial-source-control/review-center')]);qs('#fscContext').innerHTML=`<div class="warn"><b>کنترل و ممیزی مأخذ مالی</b> — این صفحه هیچ Candidate را فعال نمی‌کند و سود ناقص/نامشخص را سود قطعی نمایش نمی‌دهد.</div><div class="row two">${card('Purchase Dataset فعال',overview.purchase.active)}${card('Purchase Dataset کاندیدا',overview.purchase.candidate)}${card('FIFO فعال',overview.fifo.active)}${card('FIFO کاندیدا',overview.fifo.candidate)}</div>${reviewControls('purchase-dataset',overview.purchase)}${reviewControls('fifo-dataset',overview.fifo)}<div class="card"><div class="card-header"><h5>مرکز بررسی</h5></div><div class="card-body"><div class="row five">${(queues.queues||[]).map(queue=>`<div class="kpi"><b>${num(queue.pendingCount)}</b><span>${safe(queue.label)}</span><small>${safe(queue.responsibleRole)}</small></div>`).join('')}</div></div></div>`;window.__fscContext=overview;qsa('.fscReviewAction',qs('#fscContext')).forEach(button=>button.onclick=async()=>{const reason=['reject'].includes(button.dataset.action)?prompt('دلیل اقدام (الزامی):',''):prompt('یادداشت Audit اختیاری:','')||'';if(button.dataset.action==='reject'&&!reason)return;try{await api(`/api/accounting/financial-source-control/reviews/${button.dataset.kind}/${encodeURIComponent(button.dataset.id)}/${button.dataset.action}`,{method:'POST',body:JSON.stringify({revision:Number(button.dataset.revision),reason})});await loadOverview();}catch(error){alert(`${error.code||''} ${error.message}`);}});}
  function pager(data,load){const pages=Math.max(1,Math.ceil(Number(data.total||0)/Number(data.pageSize||50)));return `<div class="actions"><button class="mini fscPrev" ${data.page<=1?'disabled':''}>قبلی</button><span>صفحه ${num(data.page)} از ${num(pages)} — ${num(data.total)} ردیف</span><button class="mini fscNext" ${data.page>=pages?'disabled':''}>بعدی</button></div>`;}
  function bindPager(root,data,load){qs('.fscPrev',root)?.addEventListener('click',()=>load(Math.max(1,data.page-1)));qs('.fscNext',root)?.addEventListener('click',()=>load(data.page+1));}
  async function purchaseTab(){
    const tabGeneration=window.__fscPurchaseTabGeneration=(window.__fscPurchaseTabGeneration||0)+1;let requestGeneration=0,detailGeneration=0,currentView='eligible';
    const returnLabel=value=>({EXACT_ORIGIN_LINK:'تطبیق قطعی با خرید مبنا',AMBIGUOUS_RETURN:'برگشت مبهم — نیازمند بررسی',UNLINKED_RETURN:'خرید مبنا مشخص نشده',OVER_RETURN:'مقدار برگشتی بیش از ظرفیت خرید',DUPLICATE_RETURN:'برگشت تکراری — نیازمند بررسی'}[value]||value||'بدون برگشت');
    const badge=value=>({ACTIVE:'فعال',VALIDATED_CANDIDATE:'کاندیدای اعتبارسنجی‌شده',HISTORICAL:'تاریخی'}[value]||value);
    body().innerHTML=`<div class="warn"><b>ممیزی فقط‌خواندنی Purchase Dataset</b> — تغییر Dataset فقط دامنه نمایش را عوض می‌کند؛ هیچ فعال‌سازی، تأیید یا تغییر لایه انجام نمی‌شود.</div><div class="card"><div class="card-body"><div class="form-group"><label>Purchase Dataset مورد ممیزی</label><select id="fscPurchaseDataset"><option>در حال خواندن…</option></select></div><div id="fscPurchaseDatasetMeta" class="muted"></div><div class="tabs mt"><button class="btn fscPurchaseView" data-view="eligible">لایه‌های خرید قابل استفاده</button><button class="mini fscPurchaseView" data-view="pending">قیمت خرید در انتظار اصلاح</button><button class="mini fscPurchaseView" data-view="returns">مغایرت/ابهام برگشت از خرید</button></div><div class="row five mt"><input id="fscPurchaseInvoice" inputmode="numeric" placeholder="شماره فاکتور خرید"><input id="fscPurchaseReturnInvoice" inputmode="numeric" placeholder="شماره برگشت خرید"><input id="fscPurchaseItemCode" placeholder="ItemCode دقیق"><input id="fscPurchaseLineIdentity" placeholder="Purchase Line Identity"><input id="fscPurchaseSupplier" placeholder="حساب/نام دقیق تأمین‌کننده"></div><div class="actions"><button class="btn" id="fscPurchaseSearch">جست‌وجوی محدود</button><button class="mini" id="fscPurchaseClear">پاک‌کردن فیلتر</button></div></div></div><div id="fscPurchaseRows"><div class="muted">در حال آماده‌سازی…</div></div><div id="fscPurchaseDetail" class="mt"></div>`;
    const selectedDataset=()=>qs('#fscPurchaseDataset')?.value||'';
    const renderDetail=data=>{
      const purchase=data.purchase,returns=data.returns||[],origins=data.possibleOrigins||[],resolution=data.originResolution||{};
      const returnEvidence=returns.length?returns.map(row=>`<div class="info"><div class="row four"><div>شماره برگشت<br><b>${safe(row.invoiceNumber)}</b></div><div>تاریخ<br><b>${safe(row.purchaseDate)}</b></div><div>مقدار برگشتی<br><b>${safe(row.returnedQuantityExact)}</b></div><div>وضعیت تطبیق<br><b>${safe(returnLabel(row.returnLinkageClass))}</b></div><div>مرجع Header<br><b>${safe(row.returnInvHeaderReference&&row.returnInvHeaderReference!=='0'?row.returnInvHeaderReference:'فاقد مرجع')}</b></div><div>GeneralRef / فاکتور خرید<br><b>${safe(row.returnPurchaseInvoiceNoReference||'فاقد مرجع')}</b></div></div></div>`).join(''):'<div class="success">برگشت از خرید ندارد.</div>';
      const originEvidence=origins.length?`<div class="warn"><b>مبناهای احتمالی — فقط نمایش، بدون انتخاب خودکار</b><br><small>مسیر evidence: ${safe(resolution.authority||'—')} / مرجع ${safe(resolution.reference||'—')}</small><table class="table"><thead><tr><th>فاکتور</th><th>ردیف</th><th>مقدار</th><th>قیمت واحد (ریال)</th></tr></thead><tbody>${origins.map(row=>`<tr><td>${safe(row.invoiceNumber)}</td><td>${safe(row.purchaseLineIdentity)}</td><td>${safe(row.originalQuantityExact)}</td><td>${exactNumber(row.unitCostExact)}</td></tr>`).join('')}</tbody></table><b>هیچ ظرفیت خریدی به‌صورت خودکار کاهش نیافته است.</b></div>`:'';
      qs('#fscPurchaseDetail').innerHTML=`<div class="card"><div class="card-header"><h5>جزئیات read-only مأخذ خرید <button class="mini" id="fscPurchaseCloseDetail">بستن</button></h5></div><div class="card-body">${purchase?`<h5>خرید</h5><div class="row four"><div>شماره فاکتور<br><b>${safe(purchase.invoiceNumber)}</b></div><div>تاریخ<br><b>${safe(purchase.purchaseDate)}</b></div><div>کالا<br><b>${safe(purchase.itemCode)}</b><br>${safe(purchase.itemName)}</div><div>تأمین‌کننده / حساب<br><b>${safe(purchase.supplierName)}</b><br>${safe(purchase.supplierAccountNumber)}</div><div>مقدار اولیه<br><b>${safe(purchase.originalQuantityExact)}</b></div><div>قیمت واحد<br><b>${exactNumber(purchase.unitCostExact)} ریال</b></div><div>مبلغ اولیه/مبنای قابل مصرف<br><b>${exactNumber(purchase.eligibleCostExact)} ریال</b></div></div>`:'<div class="warn">خرید مبنای یکتا تعیین نشده است.</div>'}<h5>برگشت از خرید</h5>${returnEvidence}<h5>وضعیت قابل مصرف</h5><div class="row four"><div>Original Quantity<br><b>${safe(purchase?.originalQuantityExact||'0')}</b></div><div>Returned Quantity<br><b>${safe(purchase?.returnedQuantityExact||returns[0]?.returnedQuantityExact||'0')}</b></div><div>Eligible Quantity<br><b>${safe(purchase?.eligibleQuantityExact||'0')}</b></div><div>Unit Cost<br><b>${exactNumber(purchase?.unitCostExact||0)} ریال</b></div><div>Eligible Cost<br><b>${exactNumber(purchase?.eligibleCostExact||0)} ریال</b></div><div>Evidence Status<br><b>${safe(purchase?.validationStatus||returns[0]?.validationStatus||'—')}</b></div></div>${originEvidence}<details class="mt"><summary>جزئیات فنی</summary><pre>${safe(JSON.stringify(data,null,2))}</pre></details></div></div>`;
      qs('#fscPurchaseCloseDetail').onclick=()=>{detailGeneration++;qs('#fscPurchaseDetail').innerHTML='';};
    };
    const openDetail=async(identity,itemCode,itemGuid)=>{const generation=++detailGeneration;qs('#fscPurchaseDetail').innerHTML='<div class="muted">در حال خواندن زنجیره Purchase/Return…</div>';try{const data=await api('/api/accounting/financial-source-control/purchase/detail?'+new URLSearchParams({datasetId:selectedDataset(),purchaseLineIdentity:identity}));if(generation!==detailGeneration||tabGeneration!==window.__fscPurchaseTabGeneration)return;renderDetail(data);const summary=await api('/api/accounting/financial-source-control/purchase/item-summary?'+new URLSearchParams({datasetId:selectedDataset(),itemCode:itemCode||'',itemGuid:itemGuid||''}));if(generation!==detailGeneration||tabGeneration!==window.__fscPurchaseTabGeneration)return;qs('#fscPurchaseDetail .card-body').insertAdjacentHTML('beforeend',`<h5>خلاصه شواهد هزینه کالا</h5><div class="warn"><b>این بخش فقط شواهد پیشنهادی Historical Average است.</b> واجدشرایط‌بودن و تخصیص رسمی FIFO فقط با chronology هر Sale در FIFO Candidate تعیین می‌شود؛ این صفحه هیچ FIFO allocation انجام نمی‌دهد.</div><div class="row four"><div>خرید معتبر برای پیشنهاد<br><b>${num(summary.validPurchaseCount)}</b></div><div>مقدار فروش نیازمند هزینه<br><b>${safe(summary.requiredQuantityExact)}</b></div><div>مقدار دارای شواهد معتبر<br><b>${safe(summary.coveredQuantityExact)}</b></div><div>مقدار باقیمانده نامشخص<br><b>${safe(summary.remainingUnknownQuantityExact)}</b></div><div>مقدار کل شواهد Historical Average<br><b>${safe(summary.validQuantityExact)}</b></div><div>مقدار شواهد مستثنا<br><b>${safe(summary.excludedQuantityExact)}</b></div><div>میانگین موزون پیشنهادی<br><b>${exactNumber(summary.weightedValidCostExact||0)} ریال</b></div><div>خریدهای معتبر / مستثنا<br><b>${safe((summary.validPurchaseIds||[]).join(', ')||'—')} / ${safe((summary.excludedPurchaseIds||[]).join(', ')||'—')}</b></div></div><details class="mt"><summary>جزئیات فنی Evidence</summary><pre>${safe(JSON.stringify(summary,null,2))}</pre></details>`);}catch(error){if(generation===detailGeneration)qs('#fscPurchaseDetail').innerHTML=errorBox(error);}};
    const readFilters=()=>({datasetId:selectedDataset(),view:currentView,invoiceNumber:qs('#fscPurchaseInvoice').value,returnInvoiceNumber:qs('#fscPurchaseReturnInvoice').value,itemCode:qs('#fscPurchaseItemCode').value,purchaseLineIdentity:qs('#fscPurchaseLineIdentity').value,supplier:qs('#fscPurchaseSupplier').value});
    const loadRows=async(page=1)=>{const generation=++requestGeneration,params=new URLSearchParams({...readFilters(),page:String(page),pageSize:'50'});for(const [key,value]of [...params])if(!value)params.delete(key);qs('#fscPurchaseRows').innerHTML='<div class="muted">در حال خواندن bounded Purchase evidence…</div>';try{const data=await api('/api/accounting/financial-source-control/purchase/rows?'+params);if(generation!==requestGeneration||tabGeneration!==window.__fscPurchaseTabGeneration)return;const exposure=data.exposure||{};qs('#fscPurchaseRows').innerHTML=`<div class="row three"><div class="kpi"><b>${num(exposure.count)}</b><span>تعداد ردیف</span></div><div class="kpi"><b>${safe(exposure.quantityExact||0)}</b><span>Quantity exposure</span></div><div class="kpi"><b>${exposure.financialExposureExact==null?'نامعین تا تعیین مبنا':exactNumber(exposure.financialExposureExact)+' ریال'}</b><span>Financial exposure</span></div></div>${currentView==='pending'?'<div class="warn">قیمت خرید در انتظار اصلاح — این خرید در محاسبه هزینه معتبر و میانگین خرید استفاده نمی‌شود.</div>':''}<div style="overflow:auto"><table class="table"><thead><tr><th>نوع / فاکتور / تاریخ</th><th>تأمین‌کننده</th><th>کالا</th><th>مقدار</th><th>قیمت واحد</th><th>وضعیت</th><th>مشاهده</th></tr></thead><tbody>${(data.list||[]).map(row=>`<tr><td>${row.layerKind==='purchase-return'?'برگشت':'خرید'} ${safe(row.invoiceNumber)}<br><small>${safe(row.purchaseDate)}</small></td><td>${safe(row.supplierName)}<br><small>${safe(row.supplierAccountNumber)}</small></td><td>${safe(row.itemCode)}<br><small>${safe(row.itemName)}</small></td><td>${safe(row.layerKind==='purchase-return'?row.returnedQuantityExact:row.eligibleQuantityExact)}</td><td>${exactNumber(row.unitCostExact||row.grossUnitCostExact)} ریال</td><td>${safe(row.costStatus==='pending-purchase-price-correction'?'PENDING_PURCHASE_PRICE':returnLabel(row.returnLinkageClass))}</td><td><button class="mini fscPurchaseOpen" data-id="${safe(row.purchaseLineIdentity)}" data-code="${safe(row.itemCode)}" data-guid="${safe(row.itemGuid)}">مشاهده زنجیره</button></td></tr>`).join('')||'<tr><td colspan="7">نتیجه‌ای وجود ندارد.</td></tr>'}</tbody></table></div>${pager(data)}`;bindPager(qs('#fscPurchaseRows'),data,loadRows);qsa('.fscPurchaseOpen',qs('#fscPurchaseRows')).forEach(button=>button.onclick=()=>openDetail(button.dataset.id,button.dataset.code,button.dataset.guid));}catch(error){if(generation===requestGeneration)qs('#fscPurchaseRows').innerHTML=errorBox(error);}};
    const datasets=await api('/api/accounting/financial-source-control/purchase/datasets?limit=50');if(tabGeneration!==window.__fscPurchaseTabGeneration)return;const select=qs('#fscPurchaseDataset');select.innerHTML=(datasets.list||[]).map(row=>`<option value="${safe(row.datasetId)}" ${row.datasetId===datasets.defaultDatasetId?'selected':''}>${safe(row.datasetId)} — ${safe(badge(row.badge))}</option>`).join('');const showMeta=()=>{const row=(datasets.list||[]).find(value=>value.datasetId===selectedDataset());qs('#fscPurchaseDatasetMeta').innerHTML=row?`<b>${safe(badge(row.badge))}</b> | وضعیت: ${safe(row.activationStatus||row.status)} | ساخت/تکمیل: ${safe(row.createdAt||'—')} / ${safe(row.completedAt||'—')} | بازه: ${safe(row.dateFrom||'—')} تا ${safe(row.dateTo||'—')}<br>Candidate fingerprint: <code>${safe(row.candidateFingerprint||'—')}</code><br>Source fingerprint: <code>${safe(row.sourceFingerprint||'—')}</code><br>Layer fingerprint: <code>${safe(row.layerFingerprint||'—')}</code>`:'Dataset انتخاب نشده است.';};showMeta();select.onchange=()=>{requestGeneration++;detailGeneration++;qs('#fscPurchaseDetail').innerHTML='';showMeta();loadRows(1);};qsa('.fscPurchaseView').forEach(button=>button.onclick=()=>{currentView=button.dataset.view;qsa('.fscPurchaseView').forEach(value=>value.className='mini fscPurchaseView');button.className='btn fscPurchaseView';requestGeneration++;detailGeneration++;qs('#fscPurchaseDetail').innerHTML='';loadRows(1);});qs('#fscPurchaseSearch').onclick=()=>loadRows(1);qs('#fscPurchaseClear').onclick=()=>{for(const id of ['fscPurchaseInvoice','fscPurchaseReturnInvoice','fscPurchaseItemCode','fscPurchaseLineIdentity','fscPurchaseSupplier'])qs('#'+id).value='';loadRows(1);};await loadRows(1);
  }
  async function lineAction(entityId,lineIdentity,action){const note=action==='mismatch'?prompt('شرح عدم تطابق (الزامی):',''):'';if(action==='mismatch'&&!note)return;try{await api('/api/accounting/financial-source-control/line-actions',{method:'POST',body:JSON.stringify({entityType:'purchase-dataset',entityId,lineIdentity,action,note})});alert('اقدام با Audit ثبت شد.');await loadOverview();}catch(error){alert(`${error.code||''} ${error.message}`);}}
  async function gapsTab(){body().innerHTML='<div class="muted">در حال تحلیل نواقص مأخذ…</div>';const load=async(page=1)=>{const params=new URLSearchParams({page:String(page),pageSize:'50',bucket:qs('#fscGapBucket')?.value||'',item:qs('#fscGapItem')?.value||'',invoice:qs('#fscGapInvoice')?.value||''});for(const [key,value]of [...params])if(!value)params.delete(key);const data=await api('/api/accounting/financial-source-control/gaps?'+params);body().innerHTML=`<div class="row five">${(data.summary||[]).filter(row=>row.lineCount).map(row=>`<div class="kpi"><b>${num(row.saleValue)} ریال</b><span>${safe(row.bucket)}</span><small>${num(row.lineCount)} ردیف / ${num(row.affectedItems)} کالا</small></div>`).join('')||'<div class="success">نقص مأخذ ثبت‌شده‌ای برای این Dataset وجود ندارد.</div>'}</div><div class="row three"><select id="fscGapBucket"><option value="">همه علت‌ها</option>${(data.summary||[]).map(row=>`<option ${params.get('bucket')===row.bucket?'selected':''}>${safe(row.bucket)}</option>`).join('')}</select><input id="fscGapItem" placeholder="کالا" value="${safe(params.get('item')||'')}"><input id="fscGapInvoice" placeholder="فاکتور فروش" value="${safe(params.get('invoice')||'')}"></div><button class="btn" id="fscGapSearch">اعمال فیلتر</button><div style="overflow:auto"><table class="table"><thead><tr><th>فاکتور / فروشنده</th><th>کالا / دسته</th><th>مقدار / فروش</th><th>علت طبقه‌بندی‌شده</th><th>شواهد موجود</th><th>اقدام پیشنهادی</th></tr></thead><tbody>${(data.list||[]).map(row=>`<tr><td>${safe(row.saleInvoiceNumber)}<br><small>${safe(row.sellerName||row.sellerIdentity)}</small></td><td>${safe(row.itemCode)}<br><small>${safe(row.category)}</small></td><td>${num(row.quantity)}<br><small>${num(row.saleValue)} ریال</small></td><td>${safe(row.bucket)}<br><small>${safe(row.technicalReason)}</small></td><td><details><summary>مسیر تلاش</summary><pre>${safe(JSON.stringify(row.attemptedResolution,null,2))}</pre></details></td><td>${safe(row.recommendedRemediation)}</td></tr>`).join('')||'<tr><td colspan="6">نتیجه‌ای وجود ندارد.</td></tr>'}</tbody></table></div>${pager(data)}`;qs('#fscGapSearch').onclick=()=>load(1);bindPager(body(),data,load);};await load();}
  function openingForm(){return `<details class="card"><summary class="card-header"><b>ایجاد مدرک موجودی آغازین — فقط Draft</b></summary><div class="card-body"><div class="warn">هیچ هزینه‌ای خودکار تکمیل نمی‌شود. مدرک تأییدشده فقط در ساخت یک FIFO Candidate جدید قابل مصرف است.</div><div class="row four"><input id="fscOItemCode" placeholder="کد کالا"><input id="fscOItemGuid" placeholder="GUID کالا"><input id="fscODate" placeholder="تاریخ شمسی 8 رقمی"><input id="fscOQty" placeholder="مقدار"></div><div class="row four"><input id="fscOCost" placeholder="بهای واحد (ریال)"><input id="fscOSourceType" placeholder="نوع مدرک"><input id="fscORef" placeholder="شماره/مرجع مدرک"><input id="fscOAttachment" placeholder="مرجع پیوست اختیاری"></div><textarea id="fscODescription" placeholder="شرح و دلیل حسابداری"></textarea><button class="btn" id="fscOCreate">ایجاد پیش‌نویس</button></div></details>`;}
  function evidenceActions(row){if(row.evidenceType!=='OPENING_INVENTORY_EVIDENCE')return '<button class="mini" data-nav-manual>بازکردن گردش Manual Cost</button>';if(row.status==='draft'&&['admin','accounting'].includes(role()))return `<button class="mini fscEvidenceAction" data-id="${safe(row.evidenceId)}" data-action="submit" data-revision="${row.revision}">ارسال برای تأیید</button>`;if(row.status==='pending'&&['admin','manager'].includes(role()))return `<button class="mini fscEvidenceAction" data-id="${safe(row.evidenceId)}" data-action="approve" data-revision="${row.revision}">تأیید مستقل</button><button class="mini fscEvidenceAction" data-id="${safe(row.evidenceId)}" data-action="reject" data-revision="${row.revision}">رد</button>`;return '';
  }
  async function evidenceTab(){body().innerHTML='<div class="muted">در حال خواندن شواهد هزینه…</div>';const load=async(page=1)=>{const data=await api(`/api/accounting/financial-source-control/evidence?page=${page}&pageSize=50`);body().innerHTML=`<div class="warn">${safe(data.legacyWarning)}</div>${['admin','accounting'].includes(role())?openingForm():''}<div style="overflow:auto"><table class="table"><thead><tr><th>نوع / شناسه</th><th>کالا / Scope</th><th>بازه</th><th>هزینه / مقدار</th><th>ایجادکننده / تأییدکننده</th><th>وضعیت / Revision</th><th>Supersedes / Fingerprint</th><th>Audit / اقدام</th></tr></thead><tbody>${(data.list||[]).map(row=>`<tr><td>${safe(row.evidenceType)}<br><small>${safe(row.evidenceId)}</small>${row.legacyWarning?`<div class="warn">${safe(row.legacyWarning)}</div>`:''}</td><td>${safe(row.itemCode||row.itemGuid)}<br><small>${safe(row.scope)}</small></td><td>${safe(row.effectiveFrom||'—')} تا ${safe(row.effectiveTo||'باز')}</td><td>${safe(row.costExact||'—')}<br><small>${safe(row.quantityExact||'—')}</small></td><td>${safe(row.creator?.username||'—')}<br>${safe(row.approver?.username||'—')}</td><td>${safe(statusLabel(row.status))}<br>r${num(row.revision)}</td><td>${safe(row.supersedes||'—')}<br><code>${safe((row.fingerprint||'').slice(0,16))}</code></td><td><details><summary>تاریخچه</summary><pre>${safe(JSON.stringify(row.auditLog,null,2))}</pre></details>${evidenceActions(row)}</td></tr>`).join('')||'<tr><td colspan="8">مدرکی وجود ندارد.</td></tr>'}</tbody></table></div>${pager(data)}`;bindPager(body(),data,load);qsa('[data-nav-manual]').forEach(button=>button.onclick=()=>{location.hash='manual-cost-resolution';window.route();});qsa('.fscEvidenceAction').forEach(button=>button.onclick=async()=>{const reason=button.dataset.action==='reject'?prompt('دلیل رد (الزامی):',''):'';if(button.dataset.action==='reject'&&!reason)return;try{await api(`/api/accounting/financial-source-control/opening-evidence/${encodeURIComponent(button.dataset.id)}/${button.dataset.action}`,{method:'POST',body:JSON.stringify({revision:Number(button.dataset.revision),reason})});await load();await loadOverview();}catch(error){alert(`${error.code||''} ${error.message}`);}});qs('#fscOCreate')?.addEventListener('click',async()=>{const payload={itemCode:qs('#fscOItemCode').value,itemGuid:qs('#fscOItemGuid').value,openingDate:qs('#fscODate').value,quantityExact:qs('#fscOQty').value,unitCostExact:qs('#fscOCost').value,sourceType:qs('#fscOSourceType').value,sourceReference:qs('#fscORef').value,description:qs('#fscODescription').value,attachment:qs('#fscOAttachment').value?{reference:qs('#fscOAttachment').value}:null};try{await api('/api/accounting/financial-source-control/opening-evidence',{method:'POST',body:JSON.stringify(payload)});alert('پیش‌نویس ثبت شد؛ هیچ تأیید یا FIFO rebuild انجام نشد.');await load();await loadOverview();}catch(error){alert(`${error.code||''} ${error.message}`);}});};await load();}
  function exactNumber(value){if(value==null||value==='')return '—';const raw=String(value).replace(/[,،\s]/g,''),match=raw.match(/^(-?)(\d+)(?:\.(\d+))?$/);if(!match)return safe(raw);return `${match[1]}${match[2].replace(/\B(?=(\d{3})+(?!\d))/g,',')}${match[3]?`.${match[3]}`:''}`;}
  const costSourceLabel=value=>({OFFICIAL_PURCHASE_LAYER:'فاکتور خرید رسمی',MULTI_PURCHASE_LAYER:'چند لایه خرید رسمی',MANUAL_COST_PURCHASE_LAYER:'رفع هزینه خرید نامشخص — لایه خرید',MANUAL_COST_ITEM_LEGACY:'رفع هزینه خرید نامشخص — قلم قدیمی',OPENING_INVENTORY_EVIDENCE:'موجودی آغاز دوره',UNKNOWN:'هزینه خرید نامشخص'}[value]||value||'—');
  function fifoDatasetOption(title,row,selected){if(!row)return `<div class="card"><div class="card-body warn">${safe(title)} در دسترس نیست.</div></div>`;return `<button type="button" class="card fscFifoDataset" data-dataset-id="${safe(row.datasetId)}" aria-pressed="${selected?'true':'false'}" style="width:100%;text-align:right;cursor:pointer;${selected?'border:3px solid #2563eb;background:#eff6ff;':'border:1px solid #cbd5e1;'}"><div class="card-header"><h5>${safe(title)} ${selected?'<span class="success">— انتخاب‌شده</span>':''}</h5></div><div class="card-body"><b>${safe(row.datasetId)}</b><div class="row four mt"><div><small>الگوریتم</small><br>${safe(row.algorithmVersion||'—')}</div><div><small>تاریخ ساخت</small><br>${safe(row.completedAt||row.createdAt||'—')}</div><div><small>Sale Snapshot</small><br>${safe(row.sourceSaleSnapshotId||'—')}</div><div><small>Purchase Dataset</small><br>${safe(row.sourcePurchaseDatasetId||'—')}</div></div><div class="row three mt"><div><small>پوشش ارزش فروش</small><br>${Number(row.coveragePercent||0).toFixed(2)}%</div><div><small>وضعیت</small><br>${safe(statusLabel(row.activationStatus||row.status))}</div><div><small>Facts / Allocations / Exceptions</small><br>${num(row.facts)} / ${num(row.allocations)} / ${num(row.exceptions)}</div></div></div></button>`;}
  function sourceTechnicalDetails(row){return `<details class="mt"><summary>جزئیات فنی</summary><pre>${safe(JSON.stringify({saleLineId:row.saleLineId,provenanceFingerprint:row.provenanceFingerprint,sources:row.provenanceSources},null,2))}</pre></details>`;}
  function officialProvenance(row){const sources=(row.provenanceSources||[]).filter(source=>source.sourceType==='OFFICIAL_PURCHASE_LAYER');return `<div class="info"><b>مأخذ بهای تمام‌شده</b> — ${sources.length>1?'چند لایه خرید رسمی':'فاکتور خرید رسمی'}</div><div style="overflow:auto"><table class="table"><thead><tr><th>فاکتور خرید</th><th>تاریخ خرید</th><th>تأمین‌کننده</th><th>کالا</th><th>تعداد خرید</th><th>تعداد تخصیص‌یافته</th><th>قیمت واحد خرید</th><th>هزینه تخصیص‌یافته</th></tr></thead><tbody>${sources.map(source=>`<tr><td>${safe(source.purchaseInvoiceNumber||'—')}</td><td>${safe(source.purchaseInvoiceDate||'—')}</td><td>${safe(source.supplierName||source.supplierIdentity||'—')}</td><td>${safe(source.itemCode||row.itemCode)}<br><small>${safe(source.itemName||row.itemDescription||'')}</small></td><td>${exactNumber(source.purchaseQuantityExact)}</td><td>${exactNumber(source.allocatedQty)}</td><td>${exactNumber(source.unitCostExact)} ریال</td><td>${exactNumber(source.allocatedCostExact)} ریال</td></tr>`).join('')}</tbody><tfoot><tr><th colspan="5">جمع</th><th>${exactNumber(row.provenQuantityExact)}</th><th>مبلغ فروش: ${exactNumber(row.saleValueExact)}</th><th>FIFO: ${exactNumber(row.fifoCostExact)}<br>سود: ${exactNumber(row.fifoProfitExact)}</th></tr></tfoot></table></div>${sourceTechnicalDetails(row)}`;}
  function manualProvenance(row){const sources=(row.provenanceSources||[]).filter(source=>['MANUAL_COST_PURCHASE_LAYER','MANUAL_COST_ITEM_LEGACY'].includes(source.sourceType));return sources.map(source=>`<div class="info"><b>مأخذ هزینه: رفع هزینه خرید نامشخص</b></div><div class="row four"><div><small>Resolution ID</small><br>${safe(source.manualCostResolutionId||'—')}</div><div><small>Scope</small><br>${safe(source.manualCostScope||'—')}</div><div><small>بازه مؤثر</small><br>${safe(source.manualEffectiveFrom||'—')} تا ${safe(source.manualEffectiveTo||'باز')}</div><div><small>هزینه مصوب</small><br>${exactNumber(source.manualCostExact)} ریال</div><div><small>ایجادکننده</small><br>${safe(source.createdBy?.username||'—')}</div><div><small>تأییدکننده</small><br>${safe(source.approvedBy?.username||'—')}</div><div><small>تاریخ تأیید</small><br>${safe(source.approvedAt||'—')}</div><div><small>کیفیت مدرک</small><br>${safe(source.evidenceQuality||'—')}</div></div>${source.sourceType==='MANUAL_COST_ITEM_LEGACY'?'<div class="warn">این هزینه به فاکتور خرید مشخص متصل نیست.</div>':''}`).join('')+sourceTechnicalDetails(row);}
  function openingProvenance(row){const sources=(row.provenanceSources||[]).filter(source=>source.sourceType==='OPENING_INVENTORY_EVIDENCE');return sources.map(source=>`<div class="info"><b>مأخذ: موجودی آغاز دوره</b></div><div class="row four"><div><small>Evidence ID</small><br>${safe(source.openingEvidenceId||'—')}</div><div><small>تاریخ افتتاحیه</small><br>${safe(source.openingDate||'—')}</div><div><small>مقدار مدرک</small><br>${exactNumber(source.openingQuantityExact)}</div><div><small>بهای واحد</small><br>${exactNumber(source.openingUnitCostExact)} ریال</div><div><small>تعداد تخصیص‌یافته</small><br>${exactNumber(source.allocatedQty)}</div><div><small>هزینه تخصیص‌یافته</small><br>${exactNumber(source.allocatedCostExact)} ریال</div><div><small>ایجادکننده / تأییدکننده</small><br>${safe(source.openingCreatedBy?.username||'—')} / ${safe(source.openingApprovedBy?.username||'—')}</div><div><small>مرجع مدرک</small><br>${safe(source.openingSourceReference||'—')}</div></div>`).join('')+sourceTechnicalDetails(row);}
  function unresolvedProvenance(row){const partial=row.profitProvenanceStatus==='PARTIAL';return `<div class="${partial?'warn':'error'}"><b>${partial?'مأخذ هزینه ناقص':'هزینه خرید نامشخص'}</b><br>${partial?`هزینه شناخته‌شده: ${exactNumber(row.knownFifoCostExact)} ریال — مقدار بدون مأخذ: ${exactNumber(row.unresolvedQuantityExact)}`:'برای این ردیف سود FIFO نمایش داده نمی‌شود.'}</div><div class="row three"><div><small>علت اصلی</small><br>${safe((row.unresolvedReasons||[]).join('، ')||'مأخذ معتبر پیدا نشد')}</div><div><small>شواهد موجود</small><br>${(row.provenanceSources||[]).some(source=>source.sourceType!=='UNKNOWN')?'مأخذ هزینه جزئی موجود است':'مأخذ هزینه اثبات‌شده موجود نیست'}</div><div><small>اقدام پیشنهادی</small><br>${safe(row.recommendedRemediation||'بررسی حسابداری')}</div></div>${sourceTechnicalDetails(row)}`;}
  function provenanceView(row){if(row.profitProvenanceStatus!=='PROVEN')return unresolvedProvenance(row);if(['OFFICIAL_PURCHASE_LAYER','MULTI_PURCHASE_LAYER'].includes(row.costSourceType))return officialProvenance(row);if(['MANUAL_COST_PURCHASE_LAYER','MANUAL_COST_ITEM_LEGACY'].includes(row.costSourceType))return manualProvenance(row);if(row.costSourceType==='OPENING_INVENTORY_EVIDENCE')return openingProvenance(row);return unresolvedProvenance(row);}
  function fifoResultRow(row){const proven=row.profitProvenanceStatus==='PROVEN';return `<tr><td>${safe(row.saleInvoiceNo)}</td><td>${safe(row.saleDate||'—')}</td><td>${safe(row.sellerName||row.sellerIdentity)}<br><small>${safe(row.sellerIdentity)}</small></td><td>${safe(row.productCategory)}</td><td>${safe(row.itemCode)}<br><small>${safe(row.itemDescription||row.itemGuid||'')}</small></td><td>${exactNumber(row.quantityExact)}</td><td>${exactNumber(row.saleValueExact)}</td><td>${proven?exactNumber(row.fifoCostExact):row.profitProvenanceStatus==='PARTIAL'?`${exactNumber(row.knownFifoCostExact)} (ناقص)`:'—'}</td><td>${proven?exactNumber(row.fifoProfitExact):'—'}</td><td>${proven?`${Number(row.marginPercent||0).toFixed(2)}%`:'—'}</td><td>${safe(statusLabel(row.profitProvenanceStatus))}<br><small>${safe(row.profitProvenanceStatus)}</small></td><td>${safe(costSourceLabel(row.costSourceType))}<br><small>${safe(row.costSourceType)}</small></td><td><details><summary>مشاهده مأخذ</summary>${provenanceView(row)}</details></td></tr>`;}
  function fifoFilters(selectors={sellers:[],categories:[]},state=emptyFifoFilterState()){return `<div class="card"><div class="card-header"><h5>جست‌وجوی ممیزی فروش و مأخذ سود</h5></div><div class="card-body"><div class="row five"><input id="fscFifoInvoice" inputmode="numeric" placeholder="شماره دقیق فاکتور فروش" value="${safe(state.invoice)}"><input id="fscFifoItem" placeholder="کد / GUID / نام کالا" value="${safe(state.item)}"><input id="fscFifoSeller" list="fscSellerOptions" placeholder="همه فروشندگان؛ نام یا کد را جست‌وجو کنید" value="${safe(selectorValue(selectors.sellers,state.sellerIdentity,'sellerName','sellerIdentity'))}"><datalist id="fscSellerOptions">${(selectors.sellers||[]).map(row=>`<option value="${safe(selectorLabel(row.sellerName,row.sellerIdentity))}"></option>`).join('')}</datalist><input id="fscFifoCategory" list="fscCategoryOptions" placeholder="همه دسته‌بندی‌ها؛ نام رسمی را جست‌وجو کنید" value="${safe(selectorValue(selectors.categories,state.categoryGuid,'officialProductCategoryName','officialProductCategoryGuid'))}"><datalist id="fscCategoryOptions">${(selectors.categories||[]).map(row=>`<option value="${safe(selectorLabel(row.officialProductCategoryName,row.officialProductCategoryGuid))}"></option>`).join('')}</datalist><select id="fscFifoStatus"><option value="">همه وضعیت‌های مأخذ</option><option value="PROVEN" ${state.status==='PROVEN'?'selected':''}>سود با مأخذ اثبات‌شده</option><option value="PARTIAL" ${state.status==='PARTIAL'?'selected':''}>مأخذ هزینه ناقص</option><option value="UNKNOWN" ${state.status==='UNKNOWN'?'selected':''}>هزینه خرید نامشخص</option></select></div><div class="row five"><select id="fscFifoSource"><option value="">همه انواع مأخذ</option>${['OFFICIAL_PURCHASE_LAYER','MULTI_PURCHASE_LAYER','MANUAL_COST_PURCHASE_LAYER','MANUAL_COST_ITEM_LEGACY','OPENING_INVENTORY_EVIDENCE','UNKNOWN'].map(value=>`<option value="${value}" ${state.costSourceType===value?'selected':''}>${safe(costSourceLabel(value))}</option>`).join('')}</select><input id="fscFifoDateFrom" placeholder="تاریخ فروش از 14050101" value="${safe(state.dateFrom)}"><input id="fscFifoDateTo" placeholder="تاریخ فروش تا 14051229" value="${safe(state.dateTo)}"><input id="fscFifoSaleMin" inputmode="decimal" placeholder="حداقل مبلغ فروش" value="${safe(state.saleValueMin)}"><input id="fscFifoSaleMax" inputmode="decimal" placeholder="حداکثر مبلغ فروش" value="${safe(state.saleValueMax)}"></div><div class="row four"><input id="fscFifoProfitMin" inputmode="decimal" placeholder="حداقل سود FIFO" value="${safe(state.profitMin)}"><input id="fscFifoProfitMax" inputmode="decimal" placeholder="حداکثر سود FIFO" value="${safe(state.profitMax)}"><input id="fscFifoMarginMin" inputmode="decimal" placeholder="حداقل حاشیه سود %" value="${safe(state.marginMin)}"><input id="fscFifoMarginMax" inputmode="decimal" placeholder="حداکثر حاشیه سود %" value="${safe(state.marginMax)}"></div><button class="btn" id="fscFifoSearch">جست‌وجو</button> <button class="mini" id="fscFifoClear">پاک‌کردن فیلترها</button></div></div>`;}
  async function fifoTab(){
    const context=window.__fscContext?.fifo||{},active=context.active,candidate=context.candidate,allowed=[active?.datasetId,candidate?.datasetId].filter(Boolean);
    const rememberedDataset=sessionStorage.getItem(FIFO_DATASET_KEY)||window.__fscSelectedFifoDatasetId||'';
    let selectedId=allowed.includes(rememberedDataset)?rememberedDataset:(candidate?.datasetId||active?.datasetId||'');
    window.__fscSelectedFifoDatasetId=selectedId;sessionStorage.setItem(FIFO_DATASET_KEY,selectedId);
    const tabGeneration=window.__fscFifoTabGeneration=(Number(window.__fscFifoTabGeneration)||0)+1;
    const selectors=await api('/api/accounting/financial-source-control/selectors?'+new URLSearchParams({fifoDatasetId:selectedId}));
    let filterState=readStoredFifoFilters();
    if(filterState.sellerIdentity&&!selectors.sellers.some(row=>row.sellerIdentity===filterState.sellerIdentity))filterState.sellerIdentity='';
    if(filterState.categoryGuid&&!selectors.categories.some(row=>row.officialProductCategoryGuid===filterState.categoryGuid))filterState.categoryGuid='';
    filterState=storeFifoFilters(filterState);
    body().innerHTML=`<div class="warn"><b>سود نمایش‌داده‌شده فقط «سود FIFO با مأخذ اثبات‌شده» است و Total Profit نیست.</b></div><h5>انتخاب صریح FIFO Dataset</h5><div class="row two">${fifoDatasetOption('FIFO فعال',active,selectedId===active?.datasetId)}${fifoDatasetOption('FIFO کاندیدا',candidate,selectedId===candidate?.datasetId)}</div><div class="info" id="fscSelectedNotice">داده‌های نمایش‌داده‌شده از FIFO: <b>${safe(selectedId||'—')}</b></div>${fifoFilters(selectors,filterState)}<div id="fscFifoSummary"><div class="muted">در حال محاسبه خلاصه Dataset انتخاب‌شده…</div></div><div id="fscFifoResults"><div class="muted">در حال خواندن ردیف‌ها…</div></div><div class="card"><div class="card-header"><h5>پیش‌نمایش Activation</h5></div><div class="card-body"><div class="warn">Activation در این Phase مجاز و قابل اجرا نیست. این بخش فقط Impact Preview است.</div><button class="mini" id="fscPreview">نمایش Gateهای کاندیدای FIFO</button><pre id="fscPreviewOut"></pre></div></div>`;
    const readFormState=()=>storeFifoFilters({invoice:qs('#fscFifoInvoice')?.value,item:qs('#fscFifoItem')?.value,sellerIdentity:requireStableSelector(qs('#fscFifoSeller'),selectors.sellers,'sellerName','sellerIdentity','فروشنده'),categoryGuid:requireStableSelector(qs('#fscFifoCategory'),selectors.categories,'officialProductCategoryName','officialProductCategoryGuid','دسته کالا'),status:qs('#fscFifoStatus')?.value,costSourceType:qs('#fscFifoSource')?.value,dateFrom:qs('#fscFifoDateFrom')?.value,dateTo:qs('#fscFifoDateTo')?.value,saleValueMin:qs('#fscFifoSaleMin')?.value,saleValueMax:qs('#fscFifoSaleMax')?.value,profitMin:qs('#fscFifoProfitMin')?.value,profitMax:qs('#fscFifoProfitMax')?.value,marginMin:qs('#fscFifoMarginMin')?.value,marginMax:qs('#fscFifoMarginMax')?.value});
    const paramsFor=(page,state)=>{const params=new URLSearchParams({fifoDatasetId:selectedId,page:String(page),pageSize:'50',...state});for(const [key,value]of [...params])if(!value)params.delete(key);return params;};
    const renderSummary=summary=>{const states=summary.selected||{};qs('#fscSelectedNotice').innerHTML=`داده‌های نمایش‌داده‌شده از FIFO: <b>${safe(selectedId)}</b> — ${selectedId===active?.datasetId?'فعال':'کاندیدا'}`;qs('#fscFifoSummary').innerHTML=`<div class="row three">${['PROVEN','PARTIAL','UNKNOWN'].map(code=>{const row=states[code]||{};return `<div class="kpi"><b>${exactNumber(row.saleValue)} ریال</b><span>${safe(statusLabel(code))}</span><small>${num(row.lines)} ردیف / مقدار ${exactNumber(row.quantity)}</small></div>`;}).join('')}</div><div class="info">تازه اثبات‌شده: ${num(summary.delta?.newlyProven)} | تازه نامشخص: ${num(summary.delta?.newlyUnknown)} | پسرفت: ${num(summary.delta?.regressions)} | تغییر سود اثبات‌شده: ${exactNumber(summary.delta?.profitDelta)} ریال</div><details><summary>توزیع مأخذ و خلاصه فروشنده/دسته</summary><h5>توزیع مأخذ بهای تمام‌شده</h5><table class="table"><thead><tr><th>مأخذ</th><th>ردیف</th><th>فروش</th><th>هزینه FIFO</th><th>سود اثبات‌شده</th></tr></thead><tbody>${(summary.sourceDistribution||[]).map(row=>`<tr><td>${safe(costSourceLabel(row.sourceType))}</td><td>${num(row.lines)}</td><td>${exactNumber(row.saleValue)}</td><td>${exactNumber(row.fifoCost)}</td><td>${exactNumber(row.fifoProfit)}</td></tr>`).join('')}</tbody></table><h5>خلاصه فروشنده / دسته واقعی کالا</h5><table class="table"><thead><tr><th>فروشنده</th><th>دسته کالا</th><th>کل فروش</th><th>فروش اثبات‌شده</th><th>نامشخص/ناقص</th><th>سود FIFO اثبات‌شده</th><th>پوشش</th></tr></thead><tbody>${(summary.sellerCategorySummary||[]).slice(0,100).map(row=>`<tr><td>${safe(row.sellerIdentity)}</td><td>${safe(row.productCategory)}</td><td>${exactNumber(row.totalSales)}</td><td>${exactNumber(row.provenSales)}</td><td>${exactNumber(row.unknownPartialSales)}</td><td>${exactNumber(row.provenFifoProfit)}</td><td>${Number(row.coverage||0).toFixed(2)}%</td></tr>`).join('')}</tbody></table></details>`;};
    const renderLines=(lines,load)=>{qs('#fscFifoResults').innerHTML=`<h5>ریز ممیزی مأخذ سود</h5><div style="overflow:auto"><table class="table"><thead><tr><th>فاکتور فروش</th><th>تاریخ</th><th>فروشنده</th><th>دسته کالا</th><th>کالا</th><th>تعداد</th><th>مبلغ فروش</th><th>هزینه FIFO</th><th>سود FIFO اثبات‌شده</th><th>حاشیه سود</th><th>وضعیت مأخذ</th><th>نوع مأخذ</th><th>جزئیات</th></tr></thead><tbody>${(lines.list||[]).map(fifoResultRow).join('')||'<tr><td colspan="13">ردیفی مطابق فیلترها پیدا نشد.</td></tr>'}</tbody></table></div>${pager(lines)}`;bindPager(qs('#fscFifoResults'),lines,load);};
    let requestGeneration=0;
    const load=async(page=1,capture=false)=>{if(capture)filterState=readFormState();const request=++requestGeneration,params=paramsFor(page,filterState);qs('#fscFifoResults').innerHTML='<div class="muted">در حال اجرای جست‌وجوی bounded…</div>';qs('#fscFifoSummary').innerHTML='<div class="muted">در حال محاسبه خلاصه فیلترشده…</div>';let summary,lines;try{[summary,lines]=await Promise.all([api('/api/accounting/financial-source-control/fifo/summary?'+params),api('/api/accounting/financial-source-control/fifo/lines?'+params)]);}catch(error){if(tabGeneration!==window.__fscFifoTabGeneration||request!==requestGeneration)return;throw error;}if(tabGeneration!==window.__fscFifoTabGeneration||request!==requestGeneration)return;if(summary.selectedDatasetId!==selectedId||lines.datasetId!==selectedId)throw new Error('پاسخ سرور با FIFO انتخاب‌شده تطابق ندارد.');if(summary.filtersApplied?.sellerIdentity!==filterState.sellerIdentity||lines.filtersApplied?.sellerIdentity!==filterState.sellerIdentity||summary.filtersApplied?.categoryGuid!==filterState.categoryGuid||lines.filtersApplied?.categoryGuid!==filterState.categoryGuid)throw new Error('پاسخ سرور با فیلتر پایدار انتخاب‌شده تطابق ندارد.');if(Number(summary.filteredRowCount)!==Number(lines.total))throw new Error('خلاصه و جدول فیلترشده با یکدیگر تطابق ندارند.');renderSummary(summary);renderLines(lines,pageNumber=>load(pageNumber,false));};
    qsa('.fscFifoDataset').forEach(button=>button.onclick=()=>{try{filterState=readFormState();sessionStorage.setItem(FIFO_DATASET_KEY,button.dataset.datasetId);window.__fscSelectedFifoDatasetId=button.dataset.datasetId;fifoTab().catch(error=>body().innerHTML=errorBox(error));}catch(error){qs('#fscFifoResults').innerHTML=errorBox(error);}});
    qs('#fscFifoSearch').onclick=()=>load(1,true).catch(error=>{qs('#fscFifoResults').innerHTML=errorBox(error);qs('#fscFifoSummary').innerHTML=errorBox(error);});
    qs('#fscFifoClear').onclick=()=>{filterState=storeFifoFilters(emptyFifoFilterState());fifoTab().catch(error=>body().innerHTML=errorBox(error));};
    qs('#fscPreview').onclick=async()=>{const id=candidate?.datasetId;if(!id)return qs('#fscPreviewOut').textContent='کاندیدا موجود نیست.';try{const preview=await api(`/api/accounting/financial-source-control/activation-preview/fifo-dataset/${encodeURIComponent(id)}`);qs('#fscPreviewOut').textContent=JSON.stringify(preview,null,2);}catch(error){qs('#fscPreviewOut').textContent=`${error.code} ${error.message}`;}};
    await load(1,false);
  }
  async function manualCostTab(){body().innerHTML='<div class="muted">در حال خواندن گزارش تغییرناپذیر تصمیم‌های هزینه دستی…</div>';const decisions=await api('/api/accounting/financial-source-control/manual-cost/decisions?pageSize=100');body().innerHTML=`<div class="info">Financial Source Control فقط گزارش و Audit است. عملیات رفع هزینه فقط در صفحه «رفع هزینه خرید نامشخص» انجام می‌شود. <button class="mini" id="fscOpenManualCost">رفتن به workflow اصلی</button></div><div style="overflow:auto"><table class="table"><thead><tr><th>Resolution</th><th>کالا</th><th>مأخذ</th><th>پیشنهاد</th><th>نهایی</th><th>Delta</th><th>کاربر / نقش</th><th>Audit</th></tr></thead><tbody>${(decisions.list||[]).map(row=>`<tr><td>${safe(row.resolutionId)}</td><td>${safe(row.itemCode||row.itemGuid)}</td><td>${safe(row.sourceEvidence?.sourceClass||row.sourceEvidence?.method||'—')}</td><td>${exactNumber(row.suggestedCostExact)}</td><td>${exactNumber(row.finalCostExact)}</td><td>${exactNumber(row.deltaAmountExact)} / ${row.deltaPercent==null?'—':Number(row.deltaPercent).toFixed(2)+'%'}</td><td>${safe(row.accountingUser)}<br><small>${safe(row.auditLog?.at(-1)?.by?.role||'')}</small></td><td><details><summary>Audit</summary><pre>${safe(JSON.stringify(row.auditLog||[],null,2))}</pre></details></td></tr>`).join('')||'<tr><td colspan="8">تصمیم Assisted ثبت نشده است.</td></tr>'}</tbody></table></div>`;qs('#fscOpenManualCost')?.addEventListener('click',()=>{location.hash='manual-cost-resolution';window.route();});}
  const loaders={purchase:purchaseTab,gaps:gapsTab,evidence:evidenceTab,manual:manualCostTab,fifo:fifoTab};
  async function render(){if(!ROLES.includes(role())){if(typeof window.setPage==='function')window.setPage('عدم دسترسی','<div class="error">این بخش فقط برای حسابداری، مدیر و مدیر سیستم مجاز است.</div>');return;}window.setPage('کنترل منابع مالی',`<main class="main-content"><div id="fscContext"><div class="muted">در حال خواندن lineage…</div></div><div class="tabs fscTabs"><button class="btn" data-fsc="purchase">منابع خرید</button><button class="mini" data-fsc="gaps">نواقص و کسری مأخذ</button><button class="mini" data-fsc="evidence">شواهد هزینه</button><button class="mini" data-fsc="manual">گزارش هزینه دستی</button><button class="mini" data-fsc="fifo">FIFO و مأخذ سود</button></div><div id="fscBody" class="mt"><div class="muted">در حال آماده‌سازی…</div></div></main>`);qsa('[data-fsc]').forEach(button=>button.onclick=async()=>{qsa('[data-fsc]').forEach(item=>item.className='mini');button.className='btn';try{await loaders[button.dataset.fsc]();}catch(error){body().innerHTML=errorBox(error);}});try{await loadOverview();await purchaseTab();}catch(error){body().innerHTML=errorBox(error);}}
  window.__financialSourceControl={render,api};
  try{for(const value of ['accounting','manager'])if(typeof ROLE_PAGES!=='undefined'&&Array.isArray(ROLE_PAGES[value])&&!ROLE_PAGES[value].includes(PAGE))ROLE_PAGES[value].push(PAGE);}catch{}
  const inheritedMenu=window.renderMenu;
  function installMenuEntry(){const menu=qs('#menu');if(!menu)return false;menu.querySelectorAll(`[data-page="${PAGE}"]`).forEach(node=>node.remove());if(!ROLES.includes(role()))return false;const details=qsa('details',menu).find(node=>qs('summary',node)?.textContent.trim()==='ابزارهای مالی و ممیزی');if(!details)return false;const button=document.createElement('button');button.className='navbtn';button.dataset.page=PAGE;button.textContent='کنترل منابع مالی';button.onclick=event=>{event.preventDefault();location.hash=PAGE;window.route();};details.insertBefore(button,details.firstElementChild?.nextSibling||null);return true;}
  window.renderMenu=renderMenu=function(){inheritedMenu?.apply(this,arguments);installMenuEntry();};
  const shellObserver=new MutationObserver(()=>{if(installMenuEntry())shellObserver.disconnect();});
  shellObserver.observe(document.body,{childList:true,subtree:true});
  const inheritedRoute=window.route;
  window.route=route=function(){const current=location.hash.slice(1);if(current===PAGE)return render();return inheritedRoute?.apply(this,arguments);};
  try{
    window.renderMenu();
    const requested=window.__mkcrmRequestedRoute||location.hash.slice(1);
    if(requested===PAGE&&ROLES.includes(role())){
      if(typeof history!=='undefined'&&history.replaceState)history.replaceState(null,'',`#${PAGE}`);
      else location.hash=PAGE;
      window.route();
    }
  }catch{}
})();
